  assert.match(lines[2], /Design work/);
  assert.match(lines[3], /Development/);
  assert.match(lines[4], /Total:/);
});

test('renderInvoiceText shows discount on line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.ok(invoiceResult.ok);
  const r = renderInvoiceText(invoiceResult.value);
  assert.ok(r.ok);
  const text = r.value;
  assert.match(text, /€850\.00 - €85\.00 \(10%\) = €765\.00/);
});

test('renderInvoiceText shows subtotal and discount lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 15 }],
  });
  assert.ok(invoiceResult.ok);
  const r = renderInvoiceText(invoiceResult.value);
  assert.ok(r.ok);
  const text = r.value;
  assert.match(text, /Subtotal: €850\.00/);
  assert.match(text, /Discount: -€127\.50/);
  assert.match(text, /Total: €722\.50/);
});

test('renderInvoiceText does not show subtotal/discount for zero discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.ok(invoiceResult.ok);
  const r = renderInvoiceText(invoiceResult.value);
  assert.ok(r.ok);
  const text = r.value;
  assert.ok(!text.includes('Subtotal:'));
  assert.ok(!text.includes('Discount:'));
  assert.match(text, /Total:/);
});

