test('createInvoice reports DISCOUNT_INVALID for non-number discount', () => {
  const tests = ['10', true, null, undefined, {}];
  for (const discount of tests) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-03-15',
      lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: discount }],
    });
    if (discount === undefined) {
      assert.ok(r.ok, `should allow undefined discount`);
    } else {
      assert.equal(r.ok, false, `should reject discount: ${discount}`);
      assert.equal(r.error, 'DISCOUNT_INVALID');
    }
  }
});

